const {chromium}=require('playwright');const fs=require('node:fs');const assert=require('node:assert/strict');
const routes=['fancy-text-generator','schriftgenerator','generador-de-letras','letras-diferentes','font-henkan','krasivyy-shrift','ki-tu-dac-biet','letras-bonitas','yazi-stilleri','font-style','te-shu-zi-ti','caratteri-speciali','akson-phiset','font-aesthetic','lettertypes','police-d-ecriture','generator-czcionek'];
const origin='http://127.0.0.1:8765';const out='qa-shell-result';
(async()=>{fs.mkdirSync(out,{recursive:true});const b=await chromium.launch({headless:true});const rows=[];
for(const width of [320,390,768,1440]){const ctx=await b.newContext({viewport:{width,height:900},permissions:['clipboard-read','clipboard-write']});await ctx.route('**/*',r=>r.request().url().startsWith(origin)||r.request().url().startsWith('data:')?r.continue():r.abort());
for(const slug of ['edit-distance','text-tools','unicode-text-tools',...routes]){const p=await ctx.newPage();p.setDefaultTimeout(7500);const errors=[];p.on('pageerror',e=>errors.push(String(e)));try{const res=await p.goto(origin+'/'+slug+'.html');assert.equal(res.status(),200);await p.locator('.ux-tool-dropdown summary').click();const menu=p.locator('.ux-tool-menu');assert(await menu.isVisible());assert.equal(await menu.locator('.ux-tool-menu-grid a').count(),17);const href=await menu.locator('.ux-tool-menu-grid a').evaluateAll(ns=>ns.map(n=>n.getAttribute('href')));assert.deepEqual(href,[...routes.map(x=>'/'+x)]);const bb=await menu.boundingBox();assert(bb.x>=-1&&bb.x+bb.width<=width+1,JSON.stringify(bb));await p.locator('.ux-tool-dropdown summary').click();
assert(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2),'page overflow');
if(routes.includes(slug)){assert.equal(await p.locator('#lf194-root').count(),1);assert.equal(await p.locator('h1').count(),1);assert.equal(await p.locator('#lvt-intro h1').evaluate(n=>getComputedStyle(n).color),'rgb(21, 43, 67)');for(const tab of ['writer','quick','bio','pro']){await p.locator('[data-tab="'+tab+'"]').click();assert(await p.locator('#view-'+tab).isVisible());}await p.locator('[data-tab="quick"]').click();await p.locator('#quick-input').fill('Test 123');const card=p.locator('#quick-grid .lf-font-item').first();await card.waitFor();await p.waitForTimeout(250);const styled=await card.locator('.lf-font-styled').innerText();await card.click();assert.equal(await p.evaluate(()=>navigator.clipboard.readText()),styled);}
if(['text-tools','unicode-text-tools'].includes(slug)){assert.equal(await p.locator('.lv-tool-card').count(),17);assert.equal(await p.locator('.lv-tool-grid').evaluate(n=>getComputedStyle(n).display),'grid');assert.equal(await p.locator('.lv-tool-card').first().evaluate(n=>getComputedStyle(n).display),'grid');}
assert.deepEqual(errors,[]);rows.push({slug,width,status:'PASS'});if(['edit-distance','text-tools','unicode-text-tools','ki-tu-dac-biet','police-d-ecriture'].includes(slug)&&[390,1440].includes(width))await p.screenshot({path:out+'/'+slug+'-'+width+'.png',fullPage:false});}catch(e){rows.push({slug,width,status:'FAIL',error:String(e),errors});}finally{await p.close();}console.log(JSON.stringify(rows.at(-1)));}await ctx.close();}
await b.close();fs.writeFileSync(out+'/results.json',JSON.stringify(rows,null,2));if(rows.some(x=>x.status!=='PASS'))process.exitCode=1;})().catch(e=>{console.error(e);process.exitCode=1});
